-- RUN THIS IN YOUR SUPABASE SQL EDITOR

-- 1. Create user_plans table
CREATE TABLE IF NOT EXISTS user_plans (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  firebase_uid TEXT UNIQUE NOT NULL,
  plan_id TEXT NOT NULL DEFAULT 'free', -- 'free', 'codetantra', 'pro'
  plan_expiry TIMESTAMP WITH TIME ZONE, -- Null for 'free' or unlimited. Otherwise expiration date.
  ai_coach_count INT DEFAULT 0,
  ai_coach_last_reset TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  model_papers_count INT DEFAULT 0,
  model_papers_last_reset TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Create payment_logs table
CREATE TABLE IF NOT EXISTS payment_logs (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  firebase_uid TEXT NOT NULL,
  razorpay_order_id TEXT NOT NULL,
  razorpay_payment_id TEXT NOT NULL,
  plan_id TEXT NOT NULL,
  amount_paid INT NOT NULL,
  status TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. Add RLS Policies
-- Enable Row Level Security
ALTER TABLE user_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE payment_logs ENABLE ROW LEVEL SECURITY;

-- Allow anon (the frontend) to read user_plans IF they match their firebase_uid.
-- In a fully secure setup you'd verify the JWT, but here we just allow selection by firebase_uid
CREATE POLICY "Allow public read of own plan" ON user_plans
  FOR SELECT USING (true); 

-- Note: Writes to these tables will be done by the Backend (Node.js) using the Supabase Service Role Key, 
-- which bypasses RLS. So no write policies are needed for anon.

-- 4. Create co_admins table
CREATE TABLE IF NOT EXISTS co_admins (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  college_id TEXT NOT NULL,
  college_name TEXT NOT NULL,
  branch_id TEXT, -- Null if all branches
  branch_name TEXT,
  assigned_by TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. Create student_reviews table for verified student reviews & ratings
CREATE TABLE IF NOT EXISTS student_reviews (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  photo TEXT,
  email TEXT,
  branch TEXT,
  rating NUMERIC(2,1) NOT NULL DEFAULT 5.0,
  review TEXT NOT NULL,
  likes INT NOT NULL DEFAULT 0,
  verified BOOLEAN DEFAULT true,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable Row Level Security for student_reviews
ALTER TABLE student_reviews ENABLE ROW LEVEL SECURITY;

-- Allow anonymous visitors & authenticated students to read all reviews
CREATE POLICY "Allow public read of student reviews" ON student_reviews
  FOR SELECT USING (true);

-- Allow students to insert new reviews
CREATE POLICY "Allow public insert of student reviews" ON student_reviews
  FOR INSERT WITH CHECK (true);

-- Allow incrementing likes / updating reviews
CREATE POLICY "Allow public update of student reviews" ON student_reviews
  FOR UPDATE USING (true) WITH CHECK (true);

-- Allow students / admins to delete reviews
CREATE POLICY "Allow public delete of student reviews" ON student_reviews
  FOR DELETE USING (true);

-- Enable Realtime publication so like counts and new reviews broadcast immediately to all clients
ALTER PUBLICATION supabase_realtime ADD TABLE student_reviews;

